// Curaduría barata, antes de gastar nada.
// Cada tema que se descarta acá es una llamada al modelo y medio minuto de
// render que no se pagan. Lo que se escapa, lo agarra el modelo o la persona
// que aprueba, que son más caros.

const LARGO_MAXIMO = 80;

// Promesas de salud o de dinero: un canal automatizado no puede hacerlas.
const PROHIBIDO = /\b(cura|curar|curan|sana|adelgaz\w*|kilos?|dieta|tratamiento|garantizad\w*|ganá|ganar plata)\b/i;

const normalizar = (t) =>
  String(t ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .trim();

const vistos = new Map();
const salida = [];

for (const item of $input.all()) {
  const t = item.json;
  const clave = normalizar(t.tema);
  let motivo = null;

  if (clave === '') motivo = 'tema_vacio';
  else if (vistos.has(clave)) motivo = 'duplicado_de_' + vistos.get(clave);
  else if (t.hecho === true) motivo = 'ya_publicado';
  else if (clave.length > LARGO_MAXIMO) motivo = 'demasiado_largo_para_30_segundos';
  else if (PROHIBIDO.test(clave)) motivo = 'promesa_de_salud_o_dinero';

  if (clave !== '' && !vistos.has(clave)) vistos.set(clave, t.id);

  salida.push({ json: { ...t, _apto: motivo === null, _motivo: motivo } });
}

return salida;

// Uno por ejecución. El render es lo caro, y la cuenta gratuita alcanza
// para unos dieciocho videos en total: no se fabrican de a diez.
//
// Lo que ya se aprobó o se descartó queda anotado en los datos estáticos del
// flujo (lo escribe "Marcar el tema", al final).
// OJO: n8n solo guarda los datos estáticos en ejecuciones de producción, con
// el flujo activado. Ejecutando a mano vas a ver siempre el mismo tema.

const estado = $getWorkflowStaticData('global');
const cerrados = new Set(estado.cerrados ?? []);
const canal = $('El canal').first().json;

const aptos = $input
  .all()
  .map((i) => i.json)
  .filter((t) => t._apto && !cerrados.has(t.id));

if (aptos.length === 0) {
  return [{ json: { sin_temas: true, canal: canal.nombre } }];
}

const t = aptos[0];

return [
  {
    json: {
      sin_temas: false,
      id: t.id,
      tema: t.tema.trim(),
      canal: canal.nombre,
      publico: canal.publico,
      tono: canal.tono,
      quedan_despues_de_este: aptos.length - 1,
    },
  },
];

