// El guion se valida antes de buscar fotos y, sobre todo, antes de
// renderizar. Un render malo cuesta lo mismo que uno bueno.

const PALABRAS_POR_SEGUNDO = 2.5; // voz neural en castellano, aproximado
const ESCENAS = 4;
const MIN_PALABRAS = 55;
const MAX_PALABRAS = 95;

// Unsplash busca mucho mejor en inglés. Si aparecen estas palabras, la
// búsqueda salió en castellano.
const CASTELLANO = /[áéíóúñ¿¡]|\b(el|la|los|las|de|del|que|con|un|una|y)\b/i;

const contar = (t) => String(t ?? '').trim().split(/\s+/).filter(Boolean).length;
const tema = $('Elegir tema').first().json;
const g = $json.output ?? {};
const escenas = Array.isArray(g.escenas) ? g.escenas : [];
const palabras = escenas.reduce((n, e) => n + contar(e.narracion), 0);

let motivo = null;

if (g.apto === false) {
  motivo = 'el_modelo_lo_considero_no_apto: ' + (g.motivo_no_apto || 'sin motivo');
} else if (escenas.length !== ESCENAS) {
  motivo = `tiene_${escenas.length}_escenas_en_vez_de_${ESCENAS}`;
} else if (escenas.some((e) => contar(e.narracion) === 0)) {
  motivo = 'escena_sin_narracion';
} else if (palabras < MIN_PALABRAS || palabras > MAX_PALABRAS) {
  motivo = `${palabras}_palabras_fuera_de_${MIN_PALABRAS}_a_${MAX_PALABRAS}`;
} else if (escenas.some((e) => contar(e.busqueda) === 0 || CASTELLANO.test(e.busqueda))) {
  motivo = 'busqueda_vacia_o_en_castellano';
} else if (!g.titulo || g.titulo.length > 70) {
  motivo = 'titulo_vacio_o_largo';
}

return {
  json: {
    tema_id: tema.id,
    tema: tema.tema,
    titulo: g.titulo ?? null,
    escenas,
    descripcion: g.descripcion ?? null,
    hashtags: Array.isArray(g.hashtags) ? g.hashtags : [],
    palabras,
    segundos_estimados: Math.round(palabras / PALABRAS_POR_SEGUNDO),
    _valido: motivo === null,
    _motivo: motivo,
  },
};

// Una búsqueda de foto por escena. El índice viaja con cada item para no
// depender del orden más adelante.
return $input.first().json.escenas.map((e, i) => ({
  json: { indice: i + 1, narracion: e.narracion, busqueda: e.busqueda },
}));

// Una foto por escena, sin repetir, con lo que Unsplash exige para usarla:
// el nombre del fotógrafo, el enlace a su perfil y la dirección de descarga.

// Unsplash pide que los enlaces de atribución lleven el nombre de tu
// aplicación. Poné el mismo que le diste al crearla.
const APP = 'seminario_automatizacion';
const utm = `?utm_source=${APP}&utm_medium=referral`;

const escenas = $('Separar escenas').all().map((i) => i.json);
const respuestas = $input.all().map((i) => i.json);

if (escenas.length !== respuestas.length) {
  throw new Error(
    `Llegaron ${respuestas.length} respuestas de Unsplash para ${escenas.length} escenas`
  );
}

const usadas = new Set();

const conFoto = escenas.map((e, i) => {
  const f = (respuestas[i].results ?? []).find((r) => !usadas.has(r.id));
  if (!f) return { ...e, foto: null };
  usadas.add(f.id);
  return {
    ...e,
    foto: {
      id: f.id,
      // raw + parámetros de recorte: conserva el ixid que Unsplash usa para
      // contar las vistas, y llega ya en vertical.
      url: f.urls.raw + '&w=1080&h=1920&fit=crop&fm=jpg&q=80',
      descripcion: f.alt_description ?? '',
      autor: f.user.name,
      perfil: f.user.links.html + utm,
      pagina: f.links.html + utm,
      download_location: f.links.download_location,
    },
  };
});

const faltan = conFoto.filter((e) => !e.foto).map((e) => e.indice);
const autores = [...new Set(conFoto.filter((e) => e.foto).map((e) => e.foto.autor))];

return [
  {
    json: {
      escenas: conFoto,
      fotos_completas: faltan.length === 0,
      escenas_sin_foto: faltan,
      creditos_fotos: autores.length
        ? 'Fotos de ' + autores.join(', ') + ' en Unsplash'
        : '',
    },
  },
];

// El video entero es un JSON. Esto es lo que se manda a renderizar.
// Documentación: https://json2video.com/docs/v2/

const VOZ = 'es-AR-ElenaNeural'; // o es-AR-TomasNeural
const CREDITOS_SEGUNDOS = 3;

const guion = $('Validar guion').first().json;
const fotos = $('Elegir fotos').first().json;

const scenes = fotos.escenas.map((e, i) => ({
  comment: 'Escena ' + e.indice,
  elements: [
    {
      type: 'image',
      src: e.foto.url,
      resize: 'cover',
      // Un acercamiento lento, alternando: la foto quieta parece un error.
      zoom: i % 2 === 0 ? 3 : -3,
      duration: -2,
    },
    { type: 'voice', text: e.narracion, voice: VOZ },
  ],
}));

// La atribución va adentro del video, no solo en la descripción.
scenes.push({
  comment: 'Créditos',
  duration: CREDITOS_SEGUNDOS,
  'background-color': '#000000',
  elements: [
    {
      type: 'text',
      text: fotos.creditos_fotos,
      position: 'center-center',
      settings: { color: '#ffffff', 'font-size': '42px', 'text-align': 'center' },
    },
  ],
});

const movie = {
  comment: guion.titulo,
  resolution: 'instagram-story', // 1080 x 1920, vertical
  quality: 'high',
  scenes,
  elements: [
    {
      type: 'subtitles',
      language: 'es',
      settings: {
        style: 'classic-progressive',
        'font-family': 'Roboto',
        'font-size': 80,
        'max-words-per-line': 3,
        position: 'mid-bottom-center',
        'outline-width': 6,
        'outline-color': '#000000',
        'word-color': '#FFD400',
        'line-color': '#FFFFFF',
      },
    },
  ],
};

// Se cobra un crédito por segundo de video terminado.
const segundos = guion.segundos_estimados + CREDITOS_SEGUNDOS;

return [
  {
    json: {
      titulo: guion.titulo,
      descripcion: guion.descripcion,
      hashtags: guion.hashtags,
      creditos_fotos: fotos.creditos_fotos,
      creditos_estimados: segundos,
      movie,
    },
  },
];

// El libro de costos. Una fila por pieza fabricada.
//
// Precio de referencia: el plan pago más chico de JSON2Video, que hoy ronda
// 16,63 dólares por 3000 segundos. Revisalo en json2video.com/pricing.
const USD_POR_SEGUNDO = 16.63 / 3000;

const estadoRender = $input.first().json;
const r = estadoRender.movie;
const pedido = $('Armar el video').first().json;
const segundos = Math.ceil(Number(r.duration) || 0);
const restantes = estadoRender.remaining_quota?.time ?? null;

const fila = {
  fecha: new Date().toISOString().slice(0, 10),
  tema: $('Elegir tema').first().json.tema,
  titulo: pedido.titulo,
  segundos,
  estimados: pedido.creditos_estimados,
  render_segundos: r.rendering_time ?? null,
  usd_referencia: Number((segundos * USD_POR_SEGUNDO).toFixed(3)),
};

const estado = $getWorkflowStaticData('global');
estado.libro = [...(estado.libro ?? []), fila].slice(-50);

const total = estado.libro.reduce((n, f) => n + f.segundos, 0);

return [
  {
    json: {
      ...fila,
      url: r.url,
      miniatura: r.thumbnail ?? null,
      creditos_restantes: restantes,
      piezas_que_quedan: restantes === null || segundos === 0 ? null : Math.floor(restantes / segundos),
      // Gemini y Unsplash, en el nivel gratuito, no cuestan nada.
      // A precio de lista, un video por día durante un mes:
      usd_por_mes_a_un_video_por_dia: Number((fila.usd_referencia * 30).toFixed(2)),
      acumulado_segundos: total,
      piezas_en_el_libro: estado.libro.length,
    },
  },
];

// La ejecución estuvo en pausa hasta que alguien abrió uno de los dos
// enlaces o se venció el plazo. Si volvió por un enlace, trae la decisión en
// la query. Si se venció, el item es el mismo que entró a la espera.

let decision = "vencido";
if($input.first().json.data){
  decision = $input.first().json.data.approved ? "aprobar" : "rechazar";
}

const tema = $('Elegir tema').first().json;

// Aprobado o descartado, el tema se cierra y mañana sale el siguiente.
// Si nadie decidió, el tema queda abierto y se vuelve a intentar.
if (decision === 'aprobar' || decision === 'rechazar') {
  const estado = $getWorkflowStaticData('global');
  estado.cerrados = [...new Set([...(estado.cerrados ?? []), tema.id])];
}

const pieza = $('Registrar costo').first().json;

return [
  {
    json: {
      decision,
      tema_id: tema.id,
      titulo: pieza.titulo,
      url: pieza.url,
      descripcion: $('Armar el video').first().json.descripcion,
      hashtags: $('Armar el video').first().json.hashtags,
      creditos_fotos: $('Armar el video').first().json.creditos_fotos,
      segundos: pieza.segundos,
    },
  },
];

// Un solo lugar para todo lo que no terminó en un video para aprobar.
// Cada caso dice qué pasó, si se gastaron créditos y qué hacer.

const salida = [];
const tema = $('Elegir tema').first().json.tema ?? null;

for (const item of $input.all()) {
  const j = item.json;
  let etapa;
  let mensaje;
  let que_hacer;
  let gasto_creditos = false;

  if (j.movie?.status === 'error') {
    etapa = 'render_fallido';
    mensaje = j.movie.message || 'sin mensaje';
    que_hacer = 'Leer el mensaje: casi siempre es un campo mal escrito en el JSON del video. Un render fallido no se cobra.';
  } else if (j.movie?.status === 'pending' || j.movie?.status === 'running') {
    etapa = 'render_demorado';
    mensaje = 'Seguía en "' + j.movie.status + '" después del último intento.';
    que_hacer = 'No pedirlo de nuevo: probablemente termine y se cobre igual. Consultar el estado más tarde con el mismo project.';
    gasto_creditos = true;
  } else if (j.success === false) {
    etapa = 'pedido_rechazado';
    mensaje = j.message || 'sin mensaje';
    que_hacer = 'JSON2Video no aceptó el pedido. Revisar la clave y el cuerpo. No se cobró nada.';
  } else {
    const e = j.error ?? {};
    etapa = 'error_de_nodo';
    mensaje = typeof e === 'string' ? e : e.message || JSON.stringify(e).slice(0, 300);
    // El límite va primero: Unsplash lo informa con un 403, el mismo código
    // que una clave inválida. Lo que distingue es el texto, no el número.
    que_hacer = /429|rate limit/i.test(mensaje)
      ? 'Límite de pedidos: Unsplash da 50 por hora en modo demo. Esperar, no reintentar.'
      : /401|403/.test(mensaje)
        ? 'Credencial: revisar la clave de ese servicio.'
        : 'Abrir la ejecución y mirar el nodo que falló.';
  }

  salida.push({
    json: {
      etapa,
      tema,
      mensaje,
      que_hacer,
      gasto_creditos,
      ejecucion: $execution.id,
    },
  });
}

return salida;
